    단 `bash <<EOF`처럼 본문이 그대로 실행되는 경우는 확인을 받는다.
    """
    raw = (command or "").strip()
    text = scan_text(raw)
    if not text:
        return True
    if heredoc_shell_exec(raw):
        return True
    segments = chain_segments(text) or [text]
    for segment in segments:
