"""실제 세션 기록의 shell 명령으로 확인 요청 감소폭을 재는 임시 스크립트.

`git show HEAD:agent.py`(리팩터 전)와 현재 agent.py(리팩터 후)를 나란히 불러
같은 명령 집합에 대한 "자동 실행/확인 요청" 판정을 비교한다.
"""
import importlib.util
import json
import sys
from pathlib import Path

ROOT = Path.cwd()
HISTORIES = [
    Path.home() / ".local/share/llm/history_llm.json",
    Path.home() / ".local/share/llm/history_raspApi.json",
]


def load_module(name: str, path: Path):
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec)
    sys.modules[name] = mod
    spec.loader.exec_module(mod)
    return mod


def commands() -> list[str]:
    out: list[str] = []
    for path in HISTORIES:
        if not path.is_file():
            continue
        for msg in json.loads(path.read_text(encoding="utf-8")):
            for call in msg.get("tool_calls") or []:
                fn = call.get("function") or {}
                if fn.get("name") != "shell":
                    continue
                try:
                    args = json.loads(fn.get("arguments") or "{}")
                except json.JSONDecodeError:
                    continue
                if args.get("command"):
                    out.append(args["command"])
    return out


def prompts(mod, cmd: str, mode: str) -> list[str]:
    """그 모드에서 확인을 요구하는 조각 목록."""
    if mode == "none":
        return []
    auto_ws = mode == "outside"
    allow_all = mode == "risky"
    if mode == "all":
        auto_ws = allow_all = False
    if (
        mod.is_safe_command(cmd)
        or auto_ws and mod.is_workspace_command(cmd, ROOT)
        or allow_all and not mod.needs_confirm_always(cmd, ROOT)
    ):
        return []
    segments = [c for _, c in mod.split_shell_commands(cmd)] or [cmd]
    return [
        s for s in segments
        if not allow_all or mod.needs_confirm_always(s, ROOT)
    ]


def main() -> int:
    old = load_module("old_agent", Path(".old_agent.py"))
    new = load_module("agent", Path("agent.py"))
    cmds = commands()
    print(f"세션에 저장된 shell 명령 {len(cmds)}개\n")
    for mode in ("risky", "outside", "all"):
